import argparse
import getpass
import os
import secrets
import sys
import tomllib
from pathlib import Path

import tomli_w
from argon2 import PasswordHasher

ph = PasswordHasher()
DEFAULT_CONFIG = Path(os.environ.get("CONFIG_FILE", "/config/config.toml"))

def _client_conf(interface: str, use_cert: bool) -> str:
    lines = [
        "# generated by manage.py init — client config สำหรับ unbound-control",
        "remote-control:",
        "    control-enable: yes",
        f"    control-interface: {interface}",
        "    control-port: 8953",
    ]
    if use_cert:
        lines += [
            "    server-cert-file: /certs/unbound_server.pem",
            "    control-key-file: /certs/unbound_control.key",
            "    control-cert-file: /certs/unbound_control.pem",
        ]
    else:
        lines.append("    control-use-cert: no")
    return "\n".join(lines) + "\n"


def init(path: Path, control_interface: str = "127.0.0.1", use_cert: bool = True):
    if path.exists():
        print(f"{path} exists, skip"); return

    path.parent.mkdir(parents=True, exist_ok=True)
    client_conf = path.parent / "unbound-client.conf"

    path.write_text(f'''[app]
secret_key = "{secrets.token_hex(32)}"
session_https_only = false
session_max_age = 43200

[users]

[unbound]
control_bin = "/usr/sbin/unbound-control"
control_args = ["-c", "/config/unbound-client.conf"]
timeout = 10
''')
    path.chmod(0o600)
    print(f"wrote {path} (chmod 600)")

    if not client_conf.exists():
        client_conf.write_text(_client_conf(control_interface, use_cert))
        client_conf.chmod(0o644)
        print(f"wrote {client_conf}")
        if not use_cert:
            print("WARNING: control-use-cert: no — ใช้เฉพาะ LAN ที่เชื่อถือได้เท่านั้น")
    else:
        print(f"{client_conf} exists, skip")

def add_user(path: Path, name: str):
    if not path.exists():
        sys.exit(f"{path} not found; run 'init' first")
    cfg = tomllib.loads(path.read_text())
    pw = getpass.getpass(f"Password for {name}: ")
    if len(pw) < 12:
        sys.exit("password must be >= 12 characters")
    if pw != getpass.getpass("Confirm password: "):
        sys.exit("passwords do not match")
    cfg.setdefault("users", {})[name] = ph.hash(pw)
    path.write_text(tomli_w.dumps(cfg))
    path.chmod(0o600)
    print(f"user '{name}' saved")

def set_password(path: Path, name: str, password: str | None, force: bool):
    if not path.exists():
        sys.exit(f"{path} not found; run 'init' first")
    cfg = tomllib.loads(path.read_text())
    if name not in cfg.get("users", {}):
        sys.exit(f"user '{name}' not found")
    if not password:
        password = getpass.getpass(f"New password for {name}: ")
        if password != getpass.getpass("Confirm password: "):
            sys.exit("passwords do not match")
    if len(password) < 8:
        sys.exit("password must be >= 8 characters")
    cfg.setdefault("users", {})[name] = ph.hash(password)
    cfg.setdefault("force_change", {})[name] = force
    path.write_text(tomli_w.dumps(cfg))
    path.chmod(0o600)
    print(f"password updated for '{name}' (force_change={force})")


def main():
    p = argparse.ArgumentParser()
    p.add_argument("command", choices=["init", "add-user", "set-password"])
    p.add_argument("username", nargs="?")
    p.add_argument("--config", default=str(DEFAULT_CONFIG))
    p.add_argument("--control-interface", default="127.0.0.1",
                   help="IP ของ unbound-control ที่ webapp จะต่อไป (default: 127.0.0.1)")
    p.add_argument("--no-control-cert", action="store_true",
                   help="ปิด TLS ของ unbound-control (ใช้เฉพาะ LAN ที่เชื่อถือได้)")
    p.add_argument("--password", help="ใช้กับ set-password (ถ้าไม่ใส่จะถาม)")
    p.add_argument("--force", action="store_true",
                   help="บังคับให้เปลี่ยนรหัสตอน login ครั้งถัดไป")
    a = p.parse_args()
    path = Path(a.config)
    if a.command == "init":
        init(path, a.control_interface, not a.no_control_cert)
    elif a.command == "set-password":
        if not a.username: sys.exit("username required")
        set_password(path, a.username, a.password, a.force)
    else:
        if not a.username: sys.exit("username required")
        add_user(path, a.username)

if __name__ == "__main__":
    main()